// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @notice Minimal interface for the SPACE ID Agent ID registry on BSC
///         (0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F): balanceOf only,
///         mirroring the gate used by the Phase 1 ONLYAI mint.
interface IBalanceRegistry {
    function balanceOf(address account) external view returns (uint256);
}

/// @title OnlyAIPhase2ReferralSale — ONLYAI Phase 2 distribution with invitations (BNB Chain)
/// @notice Replacement Phase 2 sale contract. The first Phase 2 contract was
///         closed by the owner on 2026-10-31 after selling 140,000 ONLYAI
///         (14 packs); its unsold stock was returned to the treasury and
///         funds this contract, so the total Phase 2 distribution stays
///         capped at 150,000,000 ONLYAI across both contracts
///         (SALE_CAP here = 150,000,000 - 140,000 = 149,860,000).
///         Phase 2 sells ONLYAI that already exists; the Phase 1 mint closed
///         permanently on 2026-10-30 and no new ONLYAI can ever be minted.
///         - Only wallets holding an Agent ID (.ai) can buy.
///         - Packs: 0.00005 BNB per pack of 10,000 tokens, base limit of 10
///           packs per wallet, mirroring Phase 1.
///         - Invitations: a buyer's first purchase may name a referrer. The
///           referrer must hold an Agent ID and must already have bought at
///           least one pack in this contract. Each distinct invited buyer
///           raises the referrer's own pack limit by 1, with no ceiling on
///           the bonus (owner's decision, 2026-10-31): the practical bounds
///           are the sale cap itself and one credit per distinct invited
///           buyer. The bonus is extra purchase quota only; bonus packs are
///           bought and paid for like any other pack.
///         - The sale ends for everyone at SALE_ENDS_AT
///           (Friday, November 6, 2026, 18:00 UTC), when the NFT mint opens.
///         - Unsold tokens can be returned to the treasury by the owner once
///           the sale is closed; proceeds go to the treasury.
contract OnlyAIPhase2ReferralSale is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ------------------------------------------------------------------
    // Locked parameters (mirror Phase 1 economics; reserve-funded)
    // ------------------------------------------------------------------
    uint256 public constant SALE_CAP = 149_860_000 ether; // 150M Phase 2 allocation minus 140,000 sold by the first contract
    uint256 public constant PACK_TOKENS = 10_000 ether;
    uint256 public constant PACK_PRICE = 0.00005 ether; // 0.00005 BNB per pack
    uint256 public constant MAX_PACKS_PER_WALLET = 10;
    uint256 public constant SALE_ENDS_AT = 1793988000; // 2026-11-06 18:00:00 UTC

    /// @notice The ONLYAI token being distributed (no minting happens here).
    IERC20 public immutable token;

    /// @notice Registry checked for the buy gate (SPACE ID Agent ID on BSC).
    IBalanceRegistry public immutable agentIdRegistry;

    /// @notice Wallet that funded the reserve and receives proceeds/returns.
    address public immutable treasury;

    // ------------------------------------------------------------------
    // Sale state
    // ------------------------------------------------------------------
    bool public saleOpen;
    bool public saleClosed; // permanent once true
    uint256 public totalSold;
    mapping(address => uint256) public packsBoughtBy;

    // ------------------------------------------------------------------
    // Invitation state
    // ------------------------------------------------------------------
    /// @notice The referrer recorded for a buyer on their first purchase
    ///         (address(0) if they bought without one). Set once, never
    ///         changes, so an invited buyer can only ever credit one wallet.
    mapping(address => address) public referrerOf;

    /// @notice How many distinct invited buyers a wallet has been credited
    ///         with. The usable bonus equals this count, with no ceiling.
    mapping(address => uint256) public validInvites;

    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------
    event SaleOpened();
    event SaleClosed(uint256 totalSold);
    event PackBought(address indexed buyer, uint256 packs, uint256 tokens, uint256 paidWei);
    event ReferralCredited(address indexed referrer, address indexed buyer, uint256 totalInvites);
    event ProceedsWithdrawn(address indexed to, uint256 amountWei);
    event UnsoldReturned(address indexed to, uint256 amount);

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------
    error ZeroAddress();
    error SaleNotOpen();
    error SaleAlreadyOpen();
    error SaleHasEnded();
    error SaleIsClosed();
    error SaleNotClosed();
    error NotAgentIdHolder();
    error InvalidPackCount();
    error WalletCapExceeded();
    error SaleCapExceeded();
    error InsufficientStock();
    error WrongPayment();
    error InvalidReferrer();
    error NothingToWithdraw();
    error TransferFailed();

    constructor(address token_, address registry_, address treasury_, address initialOwner_) Ownable(initialOwner_) {
        if (token_ == address(0) || registry_ == address(0) || treasury_ == address(0)) revert ZeroAddress();
        token = IERC20(token_);
        agentIdRegistry = IBalanceRegistry(registry_);
        treasury = treasury_;
    }

    // ------------------------------------------------------------------
    // Sale lifecycle (owner)
    // ------------------------------------------------------------------
    /// @notice Opens the sale. The contract should already be funded with
    ///         ONLYAI from the treasury reserve before this is called.
    function openSale() external onlyOwner {
        if (saleOpen) revert SaleAlreadyOpen();
        if (saleClosed) revert SaleIsClosed();
        if (block.timestamp >= SALE_ENDS_AT) revert SaleHasEnded();
        saleOpen = true;
        emit SaleOpened();
    }

    /// @notice Permanently closes the sale. Irreversible by design.
    ///         May be called by the owner at any time after opening, and by
    ///         anyone once the end time has passed (to finalize the state).
    function closeSale() external {
        if (saleClosed) revert SaleIsClosed();
        if (!saleOpen) revert SaleNotOpen();
        if (msg.sender != owner() && block.timestamp < SALE_ENDS_AT) revert SaleNotOpen();
        saleOpen = false;
        saleClosed = true;
        emit SaleClosed(totalSold);
    }

    // ------------------------------------------------------------------
    // Invitation views
    // ------------------------------------------------------------------
    /// @notice Extra packs this wallet may buy thanks to its invitations:
    ///         one per distinct invited buyer, with no ceiling.
    function bonusPacksOf(address account) public view returns (uint256) {
        return validInvites[account];
    }

    /// @notice The wallet's full pack limit: base limit plus invite bonus.
    function maxPacksFor(address account) public view returns (uint256) {
        return MAX_PACKS_PER_WALLET + bonusPacksOf(account);
    }

    // ------------------------------------------------------------------
    // Gated buy
    // ------------------------------------------------------------------
    /// @notice Buy `packs` packs of ONLYAI without an invitation.
    ///         Caller must hold an Agent ID.
    function buy(uint256 packs) external payable nonReentrant {
        _buy(packs, address(0));
    }

    /// @notice Buy `packs` packs of ONLYAI, crediting `referrer` with an
    ///         invitation. The referral is recorded only on the buyer's
    ///         first purchase in this contract; a referrer passed on later
    ///         purchases is ignored. Caller must hold an Agent ID.
    /// @param referrer The inviting wallet: must hold an Agent ID, must
    ///        already have bought at least one pack here, and cannot be
    ///        the buyer. Pass address(0) for no invitation.
    function buy(uint256 packs, address referrer) external payable nonReentrant {
        _buy(packs, referrer);
    }

    function _buy(uint256 packs, address referrer) internal {
        if (!saleOpen || saleClosed) revert SaleNotOpen();
        if (block.timestamp >= SALE_ENDS_AT) revert SaleHasEnded();
        if (packs == 0) revert InvalidPackCount();
        if (packsBoughtBy[msg.sender] + packs > maxPacksFor(msg.sender)) revert WalletCapExceeded();

        uint256 tokens = packs * PACK_TOKENS;
        if (totalSold + tokens > SALE_CAP) revert SaleCapExceeded();
        if (token.balanceOf(address(this)) < tokens) revert InsufficientStock();
        if (msg.value != packs * PACK_PRICE) revert WrongPayment();
        if (agentIdRegistry.balanceOf(msg.sender) == 0) revert NotAgentIdHolder();

        // Invitation credit: first purchase only, one referrer ever.
        if (referrer != address(0) && packsBoughtBy[msg.sender] == 0 && referrerOf[msg.sender] == address(0)) {
            if (referrer == msg.sender) revert InvalidReferrer();
            if (agentIdRegistry.balanceOf(referrer) == 0) revert InvalidReferrer();
            if (packsBoughtBy[referrer] == 0) revert InvalidReferrer();
            referrerOf[msg.sender] = referrer;
            validInvites[referrer] += 1;
            emit ReferralCredited(referrer, msg.sender, validInvites[referrer]);
        }

        packsBoughtBy[msg.sender] += packs;
        totalSold += tokens;
        token.safeTransfer(msg.sender, tokens);

        emit PackBought(msg.sender, packs, tokens, msg.value);
    }

    // ------------------------------------------------------------------
    // Treasury operations
    // ------------------------------------------------------------------
    /// @notice Withdraw accumulated sale proceeds (BNB) to the treasury.
    function withdrawProceeds() external onlyOwner nonReentrant {
        uint256 amount = address(this).balance;
        if (amount == 0) revert NothingToWithdraw();
        (bool ok,) = treasury.call{value: amount}("");
        if (!ok) revert TransferFailed();
        emit ProceedsWithdrawn(treasury, amount);
    }

    /// @notice Return every unsold ONLYAI held by this contract to the
    ///         treasury. Only after the sale has been permanently closed.
    function withdrawUnsold() external onlyOwner nonReentrant {
        if (!saleClosed) revert SaleNotClosed();
        uint256 amount = token.balanceOf(address(this));
        if (amount == 0) revert NothingToWithdraw();
        token.safeTransfer(treasury, amount);
        emit UnsoldReturned(treasury, amount);
    }

    // ------------------------------------------------------------------
    // Views
    // ------------------------------------------------------------------
    function isSaleLive() external view returns (bool) {
        return saleOpen && !saleClosed && block.timestamp < SALE_ENDS_AT;
    }

    function saleRemaining() external view returns (uint256) {
        return SALE_CAP - totalSold;
    }

    function packsRemainingFor(address account) external view returns (uint256) {
        return maxPacksFor(account) - packsBoughtBy[account];
    }

    function holdsAgentId(address account) external view returns (bool) {
        return agentIdRegistry.balanceOf(account) > 0;
    }
}

