// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {Ownable, Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

interface IAgentID {
    function balanceOf(address owner) external view returns (uint256);
}

interface IAggregatorV3 {
    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

interface ISyntaxRenderer {
    function svg(uint256 id) external view returns (string memory);
    function attributes(uint256 id) external pure returns (string memory);
}

/// @title SYNTAX SOULS
/// @notice 7,777 fully on-chain coder androids on BNB Smart Chain, one per programming language soul.
///         To mint, a Binance Agentic Wallet holding an Agent ID solves its own short Java challenge
///         (see puzzle()), sends the answer with $5 in BNB (live Chainlink price, excess refunded),
///         and receives a random SYNTAX SOUL. First come, first served. Max 3 per wallet.
///         No allowlist, no team reserve. The owner can only pause and unpause.
contract SyntaxSouls is ERC721, Ownable2Step, ReentrancyGuard {
    using Strings for uint256;

    uint256 public constant MAX_SUPPLY = 7777;
    uint256 public constant MAX_PER_WALLET = 3;
    uint256 public constant MINT_USD = 5;
    uint256 public constant PRICE_MAX_AGE = 1 days;

    IAgentID public constant AGENT_ID = IAgentID(0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F);
    IAggregatorV3 public constant BNB_USD = IAggregatorV3(0x0567F2323251f0Aab15c8dFb1967E4e8A7D42aeE);

    address payable public immutable treasury;
    ISyntaxRenderer public immutable renderer;

    uint256 public totalSupply;
    bool public paused;
    mapping(address => uint256) public mintedBy;
    mapping(uint256 => uint256) private _swap; // index => tokenId + 1 (lazy Fisher-Yates over ids 1..7777)
    uint256 private _nonce;

    error NotAgentWallet();
    error NotDirectCaller();
    error MintPaused();
    error SoldOut();
    error WalletLimit();
    error WrongAnswer();
    error FeeTooLow(uint256 required, uint256 sent);
    error StalePrice();
    error TransferFailed();

    event Minted(address indexed to, uint256 indexed tokenId, uint256 feePaid);
    event PausedSet(bool paused);

    constructor(address initialOwner, address renderer_) ERC721("SYNTAX SOULS", "SOULS") Ownable(initialOwner) {
        require(initialOwner != address(0) && renderer_.code.length > 0, "args");
        treasury = payable(initialOwner);
        renderer = ISyntaxRenderer(renderer_);
    }

    // ------------------------------------------------------------------ puzzle

    /// @notice Numbers of `wallet`'s current Java challenge. Changes after each mint.
    function puzzleParams(address wallet) public view returns (uint256 a, uint256 b, uint256 n, uint256 m) {
        uint256 s = uint256(keccak256(abi.encodePacked("SYNTAX_SOULS_PUZZLE", wallet, mintedBy[wallet])));
        a = 11 + s % 89;
        b = 11 + (s >> 8) % 89;
        n = 7 + (s >> 16) % 14;
        m = 3 + (s >> 24) % 3;
    }

    /// @notice `wallet`'s current challenge as Java source. Its printed output is the mint answer.
    function puzzle(address wallet) external view returns (string memory) {
        (uint256 a, uint256 b, uint256 n, uint256 m) = puzzleParams(wallet);
        return string.concat(
            "public class Soul {\n  public static void main(String[] args) {\n    int a = ", a.toString(),
            ", b = ", b.toString(), ", n = ", n.toString(),
            ", r = 0;\n    for (int i = 1; i <= n; i++) {\n      if (i % ", m.toString(),
            " == 0) r += a * 2;\n      else r += b;\n    }\n    System.out.println(r % 1000);\n  }\n}\n"
        );
    }

    function _answer(address wallet) private view returns (uint256 r) {
        (uint256 a, uint256 b, uint256 n, uint256 m) = puzzleParams(wallet);
        for (uint256 i = 1; i <= n; i++) r += (i % m == 0) ? a * 2 : b;
        r %= 1000;
    }

    // ------------------------------------------------------------------ pricing

    /// @notice Mint fee in wei ($5 at the latest Chainlink BNB/USD price, rounded up).
    function mintPriceWei() public view returns (uint256) {
        (, int256 answer,, uint256 updatedAt,) = BNB_USD.latestRoundData();
        if (answer <= 0 || block.timestamp - updatedAt > PRICE_MAX_AGE) revert StalePrice();
        return (MINT_USD * 1e26 + uint256(answer) - 1) / uint256(answer);
    }

    // ------------------------------------------------------------------ mint

    /// @notice Mint one random SYNTAX SOUL. `answer` is the output of puzzle(msg.sender).
    ///         Send at least mintPriceWei(); any excess is refunded.
    function mint(uint256 answer) external payable nonReentrant returns (uint256 tokenId) {
        if (paused) revert MintPaused();
        if (msg.sender != tx.origin) revert NotDirectCaller();
        if (AGENT_ID.balanceOf(msg.sender) == 0) revert NotAgentWallet();
        uint256 supply = totalSupply;
        if (supply >= MAX_SUPPLY) revert SoldOut();
        if (mintedBy[msg.sender] >= MAX_PER_WALLET) revert WalletLimit();
        if (answer != _answer(msg.sender)) revert WrongAnswer();
        uint256 fee = mintPriceWei();
        if (msg.value < fee) revert FeeTooLow(fee, msg.value);

        uint256 left = MAX_SUPPLY - supply;
        uint256 rnd = uint256(
            keccak256(abi.encode(blockhash(block.number - 1), block.prevrandao, block.timestamp, msg.sender, ++_nonce, supply))
        ) % left;
        uint256 last = left - 1;
        tokenId = _at(rnd);
        if (rnd != last) _swap[rnd] = _at(last) + 1;
        if (_swap[last] != 0) delete _swap[last];

        unchecked {
            totalSupply = supply + 1;
            mintedBy[msg.sender] += 1;
        }
        _safeMint(msg.sender, tokenId);

        (bool ok,) = treasury.call{value: fee}("");
        if (!ok) revert TransferFailed();
        uint256 refund = msg.value - fee;
        if (refund > 0) {
            (ok,) = payable(msg.sender).call{value: refund}("");
            if (!ok) revert TransferFailed();
        }
        emit Minted(msg.sender, tokenId, fee);
    }

    function _at(uint256 idx) private view returns (uint256) {
        uint256 s = _swap[idx];
        return s == 0 ? idx + 1 : s - 1;
    }

    /// @notice Whether `wallet` may mint right now (ignores the answer and the fee).
    function canMint(address wallet) external view returns (bool) {
        return !paused && totalSupply < MAX_SUPPLY && mintedBy[wallet] < MAX_PER_WALLET && AGENT_ID.balanceOf(wallet) > 0;
    }

    // ------------------------------------------------------------------ metadata

    function svgOf(uint256 tokenId) external view returns (string memory) {
        return renderer.svg(tokenId);
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        string memory json = string.concat(
            '{"name":"SYNTAX SOULS #', tokenId.toString(),
            '","description":"A coder android compiled fully on-chain on BNB Chain. Minted by an AI agent that solved a Java challenge. No IPFS, no server.","image":"data:image/svg+xml;base64,',
            Base64.encode(bytes(renderer.svg(tokenId))),
            '","attributes":', renderer.attributes(tokenId), "}"
        );
        return string.concat("data:application/json;base64,", Base64.encode(bytes(json)));
    }

    // ------------------------------------------------------------------ admin

    function setPaused(bool p) external onlyOwner {
        paused = p;
        emit PausedSet(p);
    }

    function renounceOwnership() public pure override {
        revert("disabled");
    }

    receive() external payable {
        revert("no direct payments");
    }
}

contracts/ComputeRoll.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IV2Pair is IERC20 {
    function token0() external view returns (address);
    function getReserves() external view returns (uint112, uint112, uint32);
    function price0CumulativeLast() external view returns (uint256);
    function price1CumulativeLast() external view returns (uint256);
    function mint(address) external returns (uint256);
    function burn(address) external returns (uint256, uint256);
}
interface IV2Factory {
    function getPair(address, address) external view returns (address);
    function createPair(address, address) external returns (address);
}
interface IAgentIdRegistry {
    function balanceOf(address) external view returns (uint256);
    function supportsInterface(bytes4) external view returns (bool);
}
interface IV2Router {
    function factory() external view returns (address);
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256, uint256, address[] calldata, address, uint256
    ) external;
}

/// @notice Only the canonical CRL/USDT pool is taxed. Ordinary LP additions/removals
/// after launch are also pool transfers and pay this tax unless they are a strictly
/// controlled launch/refund/buyback/tax-settlement operation.
contract Roll is ERC20 {
    uint256 public constant INITIAL_SUPPLY = 1_000_000_000_000_000 * 1e18;
    uint256 public constant TAX_BPS = 50;
    address public immutable launch;
    address public pair;
    address public taxVault;
    bool public tradingOpen;
    bool private refundUnwind;

    error NotLaunch();
    error TradingClosed();
    error AlreadyConfigured();

    constructor(address launch_) ERC20("Roll", "CRL") {
        launch = launch_;
        _mint(launch_, INITIAL_SUPPLY);
    }
    modifier onlyLaunch() { if (msg.sender != launch) revert NotLaunch(); _; }
    function configure(address pair_, address vault_) external onlyLaunch {
        if (pair != address(0) || pair_ == address(0) || vault_ == address(0)) revert AlreadyConfigured();
        pair = pair_;
        taxVault = vault_;
    }
    function openTrading() external onlyLaunch { tradingOpen = true; }
    function setRefundUnwind(bool active) external onlyLaunch { refundUnwind = active; }
    function burnHeld(uint256 amount) external onlyLaunch { _burn(launch, amount); }
    function burnRefund(address account, uint256 amount) external onlyLaunch {
        if (tradingOpen) revert AlreadyConfigured();
        _burn(account, amount);
    }
    function _update(address from, address to, uint256 amount) internal override {
        if (from == address(0) || to == address(0) || amount == 0) {
            super._update(from, to, amount);
            return;
        }
        if (!tradingOpen) {
            // Pair-to-launch is permitted only inside the failed-sale unwind.
            if (from != launch && !(refundUnwind && from == pair && to == launch)) revert TradingClosed();
        } else if ((from == pair || to == pair)
            && from != launch && to != launch && from != taxVault && to != taxVault) {
            uint256 fee = Math.mulDiv(amount, TAX_BPS, 10_000);
            if (fee != 0) super._update(from, taxVault, fee);
            amount -= fee;
        }
        super._update(from, to, amount);
    }
}

library PoolMath {
    uint256 internal constant Q112 = 2 ** 112;
    uint256 internal constant FEE_FACTOR = 9_975; // PancakeSwap V2: 0.25%.

    function reserves(IV2Pair pair, address input) internal view returns (uint256 rIn, uint256 rOut) {
        (uint112 r0, uint112 r1,) = pair.getReserves();
        return pair.token0() == input ? (uint256(r0), uint256(r1)) : (uint256(r1), uint256(r0));
    }
    function amountOut(uint256 amount, uint256 rIn, uint256 rOut) internal pure returns (uint256) {
        uint256 effective = amount * FEE_FACTOR;
        return Math.mulDiv(effective, rOut, rIn * 10_000 + effective);
    }
    function impactOK(uint256 amount, uint256 reserve) internal pure returns (bool) {
        // Average execution impact, excluding the 0.25% DEX fee, <= 8%.
        return reserve != 0 && amount * FEE_FACTOR * 9_200 <= reserve * 10_000 * 800;
    }
    function maxInput(uint256 reserve) internal pure returns (uint256) {
        return Math.mulDiv(reserve, 10_000 * 800, FEE_FACTOR * 9_200);
    }
    function cumulative(IV2Pair pair, address tokenIn) internal view returns (uint256 value) {
        bool inputIs0 = pair.token0() == tokenIn;
        value = inputIs0 ? pair.price0CumulativeLast() : pair.price1CumulativeLast();
        (uint112 r0, uint112 r1, uint32 timestampLast) = pair.getReserves();
        uint32 elapsed;
        unchecked { elapsed = uint32(block.timestamp) - timestampLast; }
        if (elapsed != 0 && r0 != 0 && r1 != 0) {
            uint256 p = inputIs0 ? (uint256(r1) << 112) / r0 : (uint256(r0) << 112) / r1;
            unchecked { value += p * elapsed; }
        }
    }
}

/// @notice Permissionless settlement; no keeper can redirect proceeds or lower
/// the protocol's historical-price minimum. No automatic call from token transfers.
contract RollTaxVault is ReentrancyGuard {
    using SafeERC20 for IERC20;
    IERC20 public immutable token;
    IERC20 public immutable usdt;
    IV2Pair public immutable pair;
    IV2Router public immutable router;
    address public immutable launch;
    address public immutable treasury;
    uint256 public constant MIN_SETTLEMENT = 10 * 1e18;
    uint256 public constant ORACLE_PERIOD = 300;
    uint256 public constant ORACLE_MAX_WINDOW = 3_600;
    uint256 public constant ORACLE_MAX_AGE = 600;
    uint256 public lastObservationTime;
    uint256 public lastCumulative;
    uint256 public averagePriceX112;
    uint256 public lastOracleTime;
    uint256 public lastSettlementTime;
    bool public active;

    error NotReady();
    error PriceProtection();
    event OracleUpdated(uint256 averagePriceX112, uint256 timestamp);
    event TaxesSettled(uint256 crlIn, uint256 usdtOut);

    constructor(address token_, address usdt_, address pair_, address router_, address treasury_) {
        launch = msg.sender;
        token = IERC20(token_);
        usdt = IERC20(usdt_);
        pair = IV2Pair(pair_);
        router = IV2Router(router_);
        treasury = treasury_;
        IERC20(token_).forceApprove(router_, type(uint256).max);
    }
    function activate() external {
        if (msg.sender != launch || active) revert NotReady();
        active = true;
        lastObservationTime = block.timestamp;
        lastCumulative = PoolMath.cumulative(pair, address(token));
    }
    function updateOracle() external {
        if (!active) revert NotReady();
        uint256 elapsed = block.timestamp - lastObservationTime;
        if (elapsed < ORACLE_PERIOD) revert NotReady();
        uint256 current = PoolMath.cumulative(pair, address(token));
        if (elapsed > ORACLE_MAX_WINDOW) {
            averagePriceX112 = 0;
            lastOracleTime = 0;
        } else {
            uint256 difference;
            unchecked { difference = current - lastCumulative; }
            averagePriceX112 = difference / elapsed;
            lastOracleTime = block.timestamp;
        }
        lastCumulative = current;
        lastObservationTime = block.timestamp;
        emit OracleUpdated(averagePriceX112, block.timestamp);
    }
    function settlementQuote() public view returns (uint256 amount, uint256 quotedOut, uint256 minimumOut) {
        if (!active || averagePriceX112 == 0 || block.timestamp - lastOracleTime > ORACLE_MAX_AGE
            || block.timestamp < lastSettlementTime + 60) revert NotReady();
        (uint256 rToken, uint256 rUsdt) = PoolMath.reserves(pair, address(token));
        if (rToken == 0 || rUsdt == 0) revert NotReady();
        uint256 spot = Math.mulDiv(rUsdt, PoolMath.Q112, rToken);
        if (spot < Math.mulDiv(averagePriceX112, 9_200, 10_000)
            || spot > Math.mulDiv(averagePriceX112, 10_800, 10_000)) revert PriceProtection();
        amount = Math.min(token.balanceOf(address(this)), PoolMath.maxInput(rToken));
        uint256 historicalValue = Math.mulDiv(amount, averagePriceX112, PoolMath.Q112);
        if (historicalValue < MIN_SETTLEMENT) revert NotReady();
        quotedOut = PoolMath.amountOut(amount, rToken, rUsdt);
        // Historical minimum is deliberately stricter than allowing 8% price drift
        // plus another 8% execution impact. Trade waits if either bound fails.
        minimumOut = Math.mulDiv(historicalValue, 9_975 * 9_200, 100_000_000);
        if (minimumOut == 0 || quotedOut < minimumOut) revert PriceProtection();
    }
    function settle(uint256 deadline) external nonReentrant returns (uint256 received) {
        if (deadline < block.timestamp || deadline > block.timestamp + 120) revert NotReady();
        (uint256 amount,, uint256 minimumOut) = settlementQuote();
        lastSettlementTime = block.timestamp;
        uint256 beforeBalance = usdt.balanceOf(address(this));
        address[] memory path = new address[](2);
        path[0] = address(token);
        path[1] = address(usdt);
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(amount, minimumOut, path, address(this), deadline);
        received = usdt.balanceOf(address(this)) - beforeBalance;
        if (received < minimumOut) revert PriceProtection();
        usdt.safeTransfer(treasury, received);
        emit TaxesSettled(amount, received);
    }
}

contract ComputeRoll is ReentrancyGuard {
    using SafeERC20 for IERC20;
    // Fixed BSC SPACE ID Agent ID registry; no admin bypass or registry setter.
    address public constant AGENT_ID_REGISTRY = 0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F;
    uint256 public constant TOKENS_PER_SHARE = 10_000_000_000 * 1e18;
    uint256 public constant COLD_SHARES = 10_000;
    uint256 public constant TOTAL_SHARES = 90_000;
    uint256 public constant WALLET_LIMIT = 20;
    uint256 public constant STAGE_SIZE = 1_000;
    uint256 public constant UNIT_USDT = 1e18;
    IERC20 public immutable usdt;
    IV2Router public immutable router;
    IV2Pair public immutable pair;
    Roll public immutable token;
    RollTaxVault public immutable taxVault;
    address public immutable treasury;
    uint256 public immutable startsAt;
    uint256 public immutable endsAt;
    uint256 public sold;
    bool public launched;
    bool public failed;
    uint256[81] public stagePrice;
    mapping(address => uint256) public mintedShares;
    mapping(address => uint256) public refundableShares;
    uint256 public totalRefunded;

    error InvalidConfiguration();
    error SaleClosed();
    error ShareLimit();
    error PriceChanged();
    error PriceProtection();
    error RefundUnavailable();
    error AgentIdRequired();
    event Minted(address indexed account, uint256 shares, uint256 usdtPaid, uint256 totalSold);
    event Launched(uint256 timestamp, uint256 lpToTreasury);
    event BuybackBurned(uint256 usdtSpent, uint256 crlBurned);
    event SaleFailed(uint256 usdtRecovered, uint256 crlBurned);
    event Refunded(address indexed account, uint256 shares, uint256 usdtReturned);

    constructor(address usdt_, address router_, address treasury_, uint256 startTimestamp) {
        if (usdt_.code.length == 0 || router_.code.length == 0 || treasury_ == address(0)
            || IERC20Metadata(usdt_).decimals() != 18) revert InvalidConfiguration();
        if (AGENT_ID_REGISTRY.code.length == 0
            || !IAgentIdRegistry(AGENT_ID_REGISTRY).supportsInterface(0x80ac58cd)) revert InvalidConfiguration();
        treasury = treasury_;
        usdt = IERC20(usdt_);
        router = IV2Router(router_);
        startsAt = startTimestamp == 0 ? block.timestamp : startTimestamp;
        if (startsAt < block.timestamp) revert InvalidConfiguration();
        endsAt = startsAt + 7 days;
        Roll created = new Roll(address(this));
        token = created;
        IV2Factory factory = IV2Factory(IV2Router(router_).factory());
        address pool = factory.getPair(address(created), usdt_);
        if (pool == address(0)) pool = factory.createPair(address(created), usdt_);
        // The CRL address is new; a pre-created pair must have no LP supply.
        if (IV2Pair(pool).totalSupply() != 0) revert InvalidConfiguration();
        pair = IV2Pair(pool);
        RollTaxVault vault = new RollTaxVault(address(created), usdt_, pool, router_, treasury_);
        taxVault = vault;
        created.configure(pool, address(vault));
        IERC20(usdt_).forceApprove(router_, type(uint256).max);
        stagePrice[0] = UNIT_USDT;
        for (uint256 i = 1; i <= 80; ++i) stagePrice[i] = stagePrice[i - 1] * 11 / 10;
    }

    /// @notice Eligibility follows the actual caller's current on-chain ownership,
    /// not the wallet app, tx.origin, an NFT approval or a supplied beneficiary.
    /// Registry failure reverts (fail closed). Refunds and transfers do not use it.
    function hasAgentId(address account) public view returns (bool) {
        return account != address(0) && IAgentIdRegistry(AGENT_ID_REGISTRY).balanceOf(account) > 0;
    }
    function quoteMint(uint256 shares) public view returns (uint256 total, uint256 cold, uint256 post) {
        if (shares == 0 || shares > WALLET_LIMIT || sold + shares > TOTAL_SHARES) revert ShareLimit();
        for (uint256 i; i < shares; ++i) {
            uint256 index = sold + i;
            if (index < COLD_SHARES) { total += UNIT_USDT; ++cold; }
            else { total += stagePrice[1 + (index - COLD_SHARES) / STAGE_SIZE]; ++post; }
        }
    }
    function buybackQuote(uint256 usdtAmount) external view returns (uint256 output, bool impactAllowed) {
        (uint256 ru, uint256 rt) = PoolMath.reserves(pair, address(usdt));
        return (PoolMath.amountOut(usdtAmount, ru, rt), PoolMath.impactOK(usdtAmount, ru));
    }
    function mint(uint256 shares, uint256 maxUSDT, uint256 minimumBuybackOut, uint256 deadline) external nonReentrant {
        if (failed || block.timestamp < startsAt || (!launched && block.timestamp >= endsAt)) revert SaleClosed();
        if (!hasAgentId(msg.sender)) revert AgentIdRequired();
        if (mintedShares[msg.sender] + shares > WALLET_LIMIT) revert ShareLimit();
        if (deadline < block.timestamp || deadline > block.timestamp + 120) revert PriceProtection();
        (uint256 cost, uint256 cold, uint256 post) = quoteMint(shares);
        if (cost > maxUSDT) revert PriceChanged();
        uint256 beforeBalance = usdt.balanceOf(address(this));
        usdt.safeTransferFrom(msg.sender, address(this), cost);
        if (usdt.balanceOf(address(this)) - beforeBalance != cost) revert InvalidConfiguration();
        mintedShares[msg.sender] += shares;
        refundableShares[msg.sender] += cold;
        // Every cold share adds its exact USDT and CRL amounts to the SAME pair.
        // Direct pair minting avoids router ratio selection leaving user funds idle.
        for (uint256 i; i < cold; ++i) {
            usdt.safeTransfer(address(pair), UNIT_USDT);
            IERC20(address(token)).safeTransfer(address(pair), TOKENS_PER_SHARE);
            pair.mint(address(this));
            ++sold;
            if (sold == COLD_SHARES) _launch();
        }
        if (post != 0) {
            uint256 postCost = cost - cold * UNIT_USDT;
            uint256 buyback = postCost / 2;
            _buyback(buyback, minimumBuybackOut, deadline);
            usdt.safeTransfer(treasury, postCost - buyback);
            sold += post;
        }
        IERC20(address(token)).safeTransfer(msg.sender, shares * TOKENS_PER_SHARE);
        emit Minted(msg.sender, shares, cost, sold);
    }
    function _launch() private {
        launched = true;
        token.openTrading();
        taxVault.activate();
        uint256 lp = pair.balanceOf(address(this));
        IERC20(address(pair)).safeTransfer(treasury, lp);
        emit Launched(block.timestamp, lp);
    }
    function _buyback(uint256 amount, uint256 minimumOut, uint256 deadline) private {
        (uint256 ru, uint256 rt) = PoolMath.reserves(pair, address(usdt));
        if (!PoolMath.impactOK(amount, ru) || minimumOut == 0) revert PriceProtection();
        uint256 currentQuote = PoolMath.amountOut(amount, ru, rt);
        if (minimumOut < Math.mulDiv(currentQuote, 9_200, 10_000)) revert PriceProtection();
        address[] memory path = new address[](2);
        path[0] = address(usdt);
        path[1] = address(token);
        uint256 beforeBalance = token.balanceOf(address(this));
        router.swapExactTokensForTokensSupportingFeeOnTransferTokens(amount, minimumOut, path, address(this), deadline);
        uint256 acquired = token.balanceOf(address(this)) - beforeBalance;
        if (acquired < minimumOut) revert PriceProtection();
        token.burnHeld(acquired);
        emit BuybackBurned(amount, acquired);
    }
    function finalizeFailure() external nonReentrant {
        if (launched || failed || block.timestamp < endsAt) revert SaleClosed();
        failed = true;
        uint256 beforeUSDT = usdt.balanceOf(address(this));
        uint256 lp = pair.balanceOf(address(this));
        if (lp != 0) {
            token.setRefundUnwind(true);
            IERC20(address(pair)).safeTransfer(address(pair), lp);
            pair.burn(address(this));
            token.setRefundUnwind(false);
        }
        uint256 remaining = token.balanceOf(address(this));
        token.burnHeld(remaining);
        emit SaleFailed(usdt.balanceOf(address(this)) - beforeUSDT, remaining);
    }
    function claimRefund(uint256 shares) external nonReentrant {
        if (!failed || shares == 0 || shares > refundableShares[msg.sender]) revert RefundUnavailable();
        uint256 amount = shares * UNIT_USDT;
        if (usdt.balanceOf(address(this)) < amount) revert RefundUnavailable();
        refundableShares[msg.sender] -= shares;
        totalRefunded += shares;
        token.burnRefund(msg.sender, shares * TOKENS_PER_SHARE);
        usdt.safeTransfer(msg.sender, amount);
        emit Refunded(msg.sender, shares, amount);
    }
}

src/BiuLaunch.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IV2Router, IV2Pair} from "./interfaces/ProtocolInterfaces.sol";
import {BiuToken} from "./BiuToken.sol";
import {BiuTreasury} from "./BiuTreasury.sol";
import {BiuOracle} from "./BiuOracle.sol";
import {BiuQuota} from "./BiuQuota.sol";

/// @notice Immutable sale of a fixed supply. The sole activation privilege deletes itself.
/// Bootstrap tokens arrive immediately but cannot move until permissionless LP seeding succeeds.
contract BiuLaunch is ReentrancyGuard, BiuQuota {
    using SafeERC20 for IERC20;

    uint256 public constant MAX_SHARES = 21_000_000;
    uint256 public constant MAX_BATCH = 10;
    uint256 public constant BOOTSTRAP = 3 hours;
    uint256 public constant RETRY_WINDOW = 1 hours;
    uint256 public constant MAX_DEVIATION_BPS = 100;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    IERC20 public immutable quote;
    BiuToken public immutable token;
    BiuTreasury public immutable taxVault;
    BiuOracle public immutable oracle;
    IV2Pair public immutable pair;
    uint256 public immutable quoteUnit;

    address public activator;
    uint256 public mintStart;
    bool public launched;
    bool public aborted;
    bool public mintClosed;
    uint256 public soldShares;
    uint256 public allocatedTokens;
    uint256 public bootstrapQuote;
    uint256 public bootstrapPoolTokens;
    mapping(address => uint256) public refundableQuote;

    struct MintQuote {
        uint256 cost;
        uint256 userTokens;
        uint256 poolTokens;
        uint256 shares;
        bool closes;
    }

    error Unauthorized();
    error InvalidConfiguration();
    error NotStarted();
    error WrongPhase();
    error InvalidAmount();
    error SoldOut();
    error Slippage();
    error PriceDeviation();
    error UnsupportedQuote();
    error NothingToClaim();
    error PoolAlreadySeeded();

    event MintStarted(uint256 timestamp, uint256 bootstrapEnd, uint256 treasuryTaxEnd);
    event Minted(address indexed account, uint256 shares, uint256 paid, uint256 userTokens, uint256 poolTokens);
    event PoolOpened(uint256 quoteAdded, uint256 tokensAdded, uint256 lpBurned);
    event BootstrapAborted();
    event Refunded(address indexed account, uint256 amount);

    constructor(
        address quote_,
        address registry_,
        address factory_,
        address router_,
        address activator_,
        address treasury_
    ) BiuQuota(registry_) {
        if (
            quote_.code.length == 0 || registry_.code.length == 0 || factory_.code.length == 0
                || router_.code.length == 0 || activator_ == address(0) || treasury_ == address(0)
                || IV2Router(router_).factory() != factory_
        ) revert InvalidConfiguration();
        uint8 d = IERC20Metadata(quote_).decimals();
        if (d < 6 || d > 18) revert InvalidConfiguration();
        quote = IERC20(quote_);
        quoteUnit = 10 ** d;
        activator = activator_;
        BiuTreasury vault = new BiuTreasury(treasury_, quote_, router_);
        taxVault = vault;
        BiuToken t = new BiuToken(address(this), address(vault), quote_, factory_);
        token = t;
        pair = IV2Pair(t.pair());
        vault.initializeToken(address(t));
        oracle = new BiuOracle(t.pair(), quote_);
    }

    function startMint() external {
        if (msg.sender != activator || activator == address(0)) revert Unauthorized();
        activator = address(0);
        mintStart = block.timestamp;
        emit MintStarted(block.timestamp, block.timestamp + BOOTSTRAP, block.timestamp + 7 days);
    }

    /// @notice Discrete daily compounding; the price is quote-token atoms per share.
    function sharePrice() public view returns (uint256) {
        if (mintStart == 0) revert NotStarted();
        uint256 n = (block.timestamp - mintStart) / 1 days;
        uint256 rate = 1 ether;
        uint256 base = 1.01 ether;
        while (n != 0) {
            if (n & 1 != 0) rate = Math.mulDiv(rate, base, 1 ether);
            n >>= 1;
            if (n != 0) base = Math.mulDiv(base, base, 1 ether);
        }
        return Math.mulDiv(quoteUnit, rate, 1 ether);
    }

    /// @notice Preview is indicative: execution also synchronizes donations and checks user limits.
    function previewMint(uint256 shares) external view returns (MintQuote memory) {
        _checkSale(shares);
        return _quoteMint(shares);
    }

    function mint(uint256 shares, uint256 maxCost, uint256 minTokensOut, uint256 deadline) external nonReentrant {
        _mintShares(shares, address(0), maxCost, minTokensOut, deadline);
    }

    function mintWithReferral(uint256 shares, address referrer, uint256 maxCost, uint256 minTokensOut, uint256 deadline)
        external
        nonReentrant
    {
        _mintShares(shares, referrer, maxCost, minTokensOut, deadline);
    }

    function previewMintFor(address who, uint256 shares) external view returns (MintQuote memory q) {
        _checkSale(shares);
        q = _quoteMint(shares);
        _checkQuota(_requireAgent(who), q.shares);
    }

    function _mintShares(uint256 shares, address referrer, uint256 maxCost, uint256 minTokensOut, uint256 deadline)
        private
    {
        _checkSale(shares);
        if (block.timestamp > deadline) revert Slippage();
        uint256 id = _requireAgent(msg.sender);
        if (!launched && block.timestamp >= mintStart + BOOTSTRAP) _finalize();
        if (launched) {
            // Account for unsolicited transfers before reading the ratio. No token swap is invoked.
            pair.sync();
            oracle.checkpoint();
        }
        MintQuote memory q = _quoteMint(shares);
        if (q.cost > maxCost || q.userTokens < minTokensOut) revert Slippage();
        _consumeQuota(id, q.shares, msg.sender, referrer);
        soldShares += q.shares;
        allocatedTokens += q.userTokens + q.poolTokens;
        if (q.closes || soldShares == MAX_SHARES || allocatedTokens == token.CAP()) mintClosed = true;
        uint256 beforeBalance = quote.balanceOf(address(this));
        quote.safeTransferFrom(msg.sender, address(this), q.cost);
        if (quote.balanceOf(address(this)) - beforeBalance != q.cost) revert UnsupportedQuote();
        if (!launched) {
            bootstrapQuote += q.cost;
            bootstrapPoolTokens += q.poolTokens;
            refundableQuote[msg.sender] += q.cost;
            IERC20(address(token)).safeTransfer(msg.sender, q.userTokens);
        } else {
            quote.safeTransfer(address(pair), q.cost);
            IERC20(address(token)).safeTransfer(address(pair), q.poolTokens);
            pair.mint(DEAD);
            IERC20(address(token)).safeTransfer(msg.sender, q.userTokens);
        }
        emit Minted(msg.sender, q.shares, q.cost, q.userTokens, q.poolTokens);
    }

    /// @notice Anyone can execute after three hours; the recipient and amounts cannot be chosen.
    function finalizeLaunch() external nonReentrant {
        _finalize();
    }

    function _finalize() private {
        if (mintStart == 0) revert NotStarted();
        if (launched || aborted || block.timestamp < mintStart + BOOTSTRAP) revert WrongPhase();
        uint256 u = bootstrapQuote;
        uint256 b = bootstrapPoolTokens;
        if (u == 0 || b == 0) revert InvalidAmount();
        // Bootstrap holders cannot transfer Biu, so outsiders cannot seed LP before this operation.
        if (pair.totalSupply() != 0) revert PoolAlreadySeeded();
        // Direct pair mint tolerates a pre-existing one-sided USDT reserve (donation + sync).
        // Any failure rolls back both transfers, accounting, and the launched flag together.
        quote.safeTransfer(address(pair), u);
        IERC20(address(token)).safeTransfer(address(pair), b);
        uint256 lp = pair.mint(DEAD);
        oracle.initialize();
        launched = true;
        bootstrapQuote = 0;
        bootstrapPoolTokens = 0;
        emit PoolOpened(u, b, lp);
    }

    /// @notice Failed launch only: 1h retry after the 3h subscription. Never available after launch.
    /// Finalize and abort are mutually exclusive; the first successful transaction settles the phase.
    function abortBootstrap() external nonReentrant {
        if (mintStart == 0) revert NotStarted();
        if (launched || aborted || block.timestamp < mintStart + BOOTSTRAP + RETRY_WINDOW) revert WrongPhase();
        aborted = true;
        mintClosed = true;
        emit BootstrapAborted();
    }

    function claimRefund() external nonReentrant {
        if (!aborted) revert WrongPhase();
        uint256 amount = refundableQuote[msg.sender];
        if (amount == 0) revert NothingToClaim();
        refundableQuote[msg.sender] = 0;
        quote.safeTransfer(msg.sender, amount);
        emit Refunded(msg.sender, amount);
    }

    function _checkSale(uint256 shares) private view {
        if (mintStart == 0) revert NotStarted();
        if (mintClosed || aborted || soldShares == MAX_SHARES) revert SoldOut();
        if (shares == 0 || shares > MAX_BATCH) revert InvalidAmount();
    }

    function _quoteMint(uint256 shares) private view returns (MintQuote memory q) {
        shares = Math.min(shares, MAX_SHARES - soldShares);
        uint256 price = sharePrice();
        q.shares = shares;
        q.cost = price * shares;
        if (!launched) {
            // Preview at/after the deadline requires a separate finalize, so no stale bootstrap quote.
            if (block.timestamp >= mintStart + BOOTSTRAP) revert WrongPhase();
            q.userTokens = shares * 0.5 ether;
            q.poolTokens = q.userTokens;
            return q;
        }
        uint256 spot = oracle.spotPrice();
        uint256 refPrice = oracle.referencePrice();
        if (
            spot == 0 || refPrice == 0
                || (spot > refPrice ? spot - refPrice : refPrice - spot)
                    > Math.mulDiv(refPrice, MAX_DEVIATION_BPS, 10_000)
        ) revert PriceDeviation();
        uint256 protectedPrice = Math.max(spot, refPrice);
        (uint112 r0, uint112 r1,) = pair.getReserves();
        uint256 rB = pair.token0() == address(token) ? r0 : r1;
        uint256 rU = pair.token0() == address(token) ? r1 : r0;
        (q.userTokens, q.poolTokens) = _amounts(q.cost, protectedPrice, rB, rU);
        uint256 remaining = token.CAP() - allocatedTokens;
        if (q.userTokens + q.poolTokens >= remaining) {
            if (remaining < 4) revert SoldOut();
            // Reserve two token wei for the two rounding operations; pull only the smaller cost.
            q.cost = Math.mulDiv(q.cost, remaining - 2, q.userTokens + q.poolTokens);
            (q.userTokens, q.poolTokens) = _amounts(q.cost, protectedPrice, rB, rU);
            q.shares = Math.ceilDiv(q.cost, price);
            q.closes = true;
        }
        if (q.cost == 0 || q.userTokens == 0 || q.poolTokens == 0 || q.userTokens + q.poolTokens > remaining) {
            revert SoldOut();
        }
    }

    function _amounts(uint256 cost, uint256 protectedPrice, uint256 rB, uint256 rU)
        private
        pure
        returns (uint256 userB, uint256 poolB)
    {
        userB = Math.mulDiv(cost, 1 ether * 10_000, protectedPrice * 9_900);
        poolB = Math.mulDiv(cost, rB, rU, Math.Rounding.Ceil);
    }
}

