// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IV2Pair} from "./interfaces/ProtocolInterfaces.sol";

/// @notice Permissionless cumulative-price observation. Only Mint is price-guarded; ERC20 trades are not.
contract BiuOracle {
    uint256 public constant PERIOD = 5 minutes;
    uint256 private constant Q112 = 1 << 112;
    IV2Pair public immutable pair;
    address public immutable launch;
    bool public immutable tokenIs0;
    bool public initialized;
    uint256 public observationCumulative;
    uint32 public observationTimestamp;
    uint256 public storedReference;

    error Unauthorized();
    error NotReady();
    event Checkpoint(uint256 referencePrice, uint32 timestamp);

    constructor(address pair_, address quote_) {
        pair = IV2Pair(pair_);
        launch = msg.sender;
        tokenIs0 = pair.token1() == quote_;
    }

    function initialize() external {
        if (msg.sender != launch || initialized) revert Unauthorized();
        (uint256 cum, uint32 now32, uint256 spot) = _current();
        if (spot == 0) revert NotReady();
        initialized = true;
        observationCumulative = cum;
        observationTimestamp = now32;
        storedReference = spot;
        emit Checkpoint(spot, now32);
    }

    function referencePrice() public view returns (uint256) {
        if (!initialized) revert NotReady();
        (uint256 cum, uint32 now32,) = _current();
        uint32 elapsed;
        unchecked {
            elapsed = now32 - observationTimestamp;
        }
        if (elapsed < PERIOD) return storedReference;
        uint256 delta;
        unchecked {
            delta = cum - observationCumulative;
        }
        return Math.mulDiv(delta / elapsed, 1 ether, Q112);
    }

    function checkpoint() external returns (uint256 price) {
        if (!initialized) revert NotReady();
        (uint256 cum, uint32 now32,) = _current();
        uint32 elapsed;
        unchecked {
            elapsed = now32 - observationTimestamp;
        }
        if (elapsed < PERIOD) return storedReference;
        uint256 delta;
        unchecked {
            delta = cum - observationCumulative;
        }
        price = Math.mulDiv(delta / elapsed, 1 ether, Q112);
        if (price == 0) revert NotReady();
        observationCumulative = cum;
        observationTimestamp = now32;
        storedReference = price;
        emit Checkpoint(price, now32);
    }

    /// @return spot Quote-token atoms per 1e18 Biu atoms (supports quote decimals 6..18).
    function spotPrice() external view returns (uint256 spot) {
        (,, spot) = _current();
    }

    function _current() private view returns (uint256 cum, uint32 now32, uint256 spot) {
        (uint112 r0, uint112 r1, uint32 last) = pair.getReserves();
        now32 = uint32(block.timestamp);
        if (r0 == 0 || r1 == 0) return (0, now32, 0);
        uint256 rToken = tokenIs0 ? r0 : r1;
        uint256 rQuote = tokenIs0 ? r1 : r0;
        spot = Math.mulDiv(rQuote, 1 ether, rToken);
        cum = tokenIs0 ? pair.price0CumulativeLast() : pair.price1CumulativeLast();
        uint32 elapsed;
        unchecked {
            elapsed = now32 - last;
            cum += ((rQuote << 112) / rToken) * elapsed;
        }
    }
}

src/BiuQuota.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IAgentRegistry} from "./interfaces/ProtocolInterfaces.sol";

/// @notice Identity-based paid Mint allowances, accounted entirely on-chain.
/// No administrator, signer, social-task verifier or reward withdrawal exists.
abstract contract BiuQuota {
    uint256 public constant BASE_PER_ID = 10;
    IAgentRegistry public immutable registry;
    mapping(uint256 => uint256) public mintedCount;
    mapping(uint256 => uint256) public extraQuota;
    mapping(uint256 => bool) public paidOnce;
    mapping(uint256 => address) public invitedBy;

    error NotAgent();
    error QuotaExceeded();
    event InviteCredited(address indexed referrer, uint256 indexed referrerId, uint256 indexed invitedId);

    constructor(address registry_) {
        registry = IAgentRegistry(registry_);
    }

    function quotaOf(uint256 id) public view returns (uint256) {
        return BASE_PER_ID + extraQuota[id];
    }

    function remainingFor(address who) external view returns (uint256) {
        uint256 id = _requireAgent(who);
        return quotaOf(id) - mintedCount[id];
    }

    function _requireAgent(address who) internal view returns (uint256 id) {
        string memory handle = registry.handleOf(who);
        id = uint256(keccak256(bytes(handle)));
        if (bytes(handle).length == 0 || registry.ownerOf(id) != who) revert NotAgent();
    }

    function _checkQuota(uint256 id, uint256 shares) internal view {
        if (mintedCount[id] + shares > quotaOf(id)) revert QuotaExceeded();
    }

    /// @dev Called inside the Launch's nonReentrant Mint. Payment/LP failures also revert these writes.
    function _consumeQuota(uint256 id, uint256 shares, address who, address referrer) internal {
        _checkQuota(id, shares);
        mintedCount[id] += shares;
        if (paidOnce[id]) return;
        paidOnce[id] = true;
        if (referrer == address(0) || referrer == who) return;
        // Invalid/expired referral data does not prevent an otherwise valid paid Mint.
        try registry.handleOf(referrer) returns (string memory handle) {
            if (bytes(handle).length == 0) return;
            uint256 rid = uint256(keccak256(bytes(handle)));
            if (rid == id) return;
            try registry.ownerOf(rid) returns (address owner) {
                if (owner != referrer) return;
                invitedBy[id] = referrer;
                extraQuota[rid] += 1;
                emit InviteCredited(referrer, rid, id);
            } catch {}
        } catch {}
    }
}

