// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IV2Factory, ILaunchState} from "./interfaces/ProtocolInterfaces.sol";

/// @notice Fixed supply. No owner, upgrade, blacklist, mint or confiscation entrypoint.
/// Taxes apply only to the immutable canonical V2 pair. Other markets are permissionless.
contract BiuToken is ERC20 {
    /// @notice Published project website; metadata only, never used for authorization or execution.
    string public constant WEBSITE = "https://biubiubiu.space";
    uint256 public constant CAP = 21_000_000 ether;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    address public immutable launch;
    address public immutable taxVault;
    address public immutable pair;

    error ZeroAddress();
    error TradingNotOpen();

    constructor(address launch_, address taxVault_, address quote_, address factory_)
        ERC20("Binance ID Utopia", "Biu")
    {
        if (launch_ == address(0) || taxVault_ == address(0) || quote_ == address(0)) {
            revert ZeroAddress();
        }
        launch = launch_;
        taxVault = taxVault_;
        address existing = IV2Factory(factory_).getPair(address(this), quote_);
        pair = existing == address(0) ? IV2Factory(factory_).createPair(address(this), quote_) : existing;
        _mint(launch_, CAP);
    }

    function taxRates() public view returns (uint256 buyBps, uint256 sellBps, uint256 treasuryBps) {
        uint256 start = ILaunchState(launch).mintStart();
        bool treasuryActive = start != 0 && block.timestamp < start + 7 days;
        return (treasuryActive ? 100 : 0, treasuryActive ? 200 : 100, treasuryActive ? 100 : 0);
    }

    function _update(address from, address to, uint256 value) internal override {
        if (from == address(0)) {
            super._update(from, to, value);
            return;
        }
        // Protocol distribution/seeding and the vault's own fee conversion cannot recurse into taxes.
        // The vault has no facility for spending on behalf of arbitrary users.
        if (from == launch || from == taxVault) {
            super._update(from, to, value);
            return;
        }
        if (!ILaunchState(launch).launched()) revert TradingNotOpen();
        (uint256 buyBps,, uint256 treasuryBps) = taxRates();
        if (from == pair) {
            uint256 fee = value * buyBps / 10_000;
            if (fee != 0) super._update(from, taxVault, fee);
            super._update(from, to, value - fee);
        } else if (to == pair) {
            uint256 burnAmount = value / 100;
            uint256 treasuryAmount = value * treasuryBps / 10_000;
            if (burnAmount != 0) super._update(from, DEAD, burnAmount);
            if (treasuryAmount != 0) super._update(from, taxVault, treasuryAmount);
            super._update(from, to, value - burnAmount - treasuryAmount);
        } else {
            super._update(from, to, value);
        }
    }
}

