// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IV2Router} from "./interfaces/ProtocolInterfaces.sol";

/// @notice Historical Treasury tax only. This contract never holds Mint proceeds or LP receipts.
/// Conversion is optional and never called from a token transfer, swap or Mint.
contract BiuTreasury is ReentrancyGuard {
    using SafeERC20 for IERC20;
    address public immutable beneficiary;
    address public immutable initializer;
    address public immutable quote;
    IV2Router public immutable router;
    IERC20 public token;

    error Unauthorized();
    error AlreadyInitialized();
    error InvalidParameters();
    event Claimed(uint256 amount);
    event Converted(uint256 amount, uint256 minBnbOut);

    constructor(address beneficiary_, address quote_, address router_) {
        if (beneficiary_ == address(0) || quote_ == address(0) || router_ == address(0)) revert InvalidParameters();
        beneficiary = beneficiary_;
        initializer = msg.sender;
        quote = quote_;
        router = IV2Router(router_);
    }

    function initializeToken(address token_) external {
        if (msg.sender != initializer) revert Unauthorized();
        if (address(token) != address(0)) revert AlreadyInitialized();
        if (token_ == address(0)) revert InvalidParameters();
        token = IERC20(token_);
    }

    function claimInKind(uint256 amount) external nonReentrant {
        if (msg.sender != beneficiary) revert Unauthorized();
        token.safeTransfer(beneficiary, amount);
        emit Claimed(amount);
    }

    /// @notice The beneficiary accepts slippage on their own already-earned fees only.
    /// A router failure reverts this isolated operation; claimInKind remains available.
    function convertToBNB(uint256 amount, uint256 minBnbOut, uint256 deadline) external nonReentrant {
        if (msg.sender != beneficiary) revert Unauthorized();
        if (amount == 0 || minBnbOut == 0 || deadline < block.timestamp || deadline > block.timestamp + 5 minutes) {
            revert InvalidParameters();
        }
        address[] memory path = new address[](3);
        path[0] = address(token);
        path[1] = quote;
        path[2] = router.WETH();
        token.forceApprove(address(router), amount);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(amount, minBnbOut, path, beneficiary, deadline);
        token.forceApprove(address(router), 0);
        emit Converted(amount, minBnbOut);
    }
}

