// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

interface IV2Factory {
    function getPair(address, address) external view returns (address);
    function createPair(address, address) external returns (address);
}

interface IV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112, uint112, uint32);
    function totalSupply() external view returns (uint256);
    function balanceOf(address) external view returns (uint256);
    function mint(address to) external returns (uint256);
    function swap(uint256 amount0, uint256 amount1, address to, bytes calldata data) external;
    function sync() external;
    function skim(address to) external;
    function price0CumulativeLast() external view returns (uint256);
    function price1CumulativeLast() external view returns (uint256);
}

interface IAgentRegistry {
    function handleOf(address) external view returns (string memory);
    function ownerOf(uint256) external view returns (address);
}

interface ILaunchState {
    function mintStart() external view returns (uint256);
    function launched() external view returns (bool);
}

interface IV2Router {
    function factory() external view returns (address);
    function WETH() external view returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

src/AgentGenesis.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC2981} from "@openzeppelin/contracts/token/common/ERC2981.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

interface IAgentArt {
    function tokenURI(string calldata collection, uint256 id, bool miner, uint256 weight) external view returns (string memory);
    function contractURI(string calldata collection, address feeRecipient, uint256 feeBps) external view returns (string memory);
}

interface IAgentId {
    function ownerOf(uint256 tokenId) external view returns (address);
    function balanceOf(address owner) external view returns (uint256);
}

interface IAggregatorV3 {
    function decimals() external view returns (uint8);
    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80);
}

/// @title AgentGenesis - Agent ID gated, earned (PoW) genesis NFT with paid ladder,
///        in-contract referral / holder-dividend / treasury split, 3->1 Miner fusion,
///        built-in escrow-free BNB marketplace and ERC-2981 royalty.
/// @notice No admin over money: there is no withdraw, pause, price, treasury, gate or art setter.
///         Art + metadata are rendered fully on-chain by the immutable AgentArt contract.
///         The owner can ONLY set an optional metadata base URI override, and can renounce.
contract AgentGenesis is ERC721, ERC2981, Ownable, ReentrancyGuard {
    using Strings for uint256;

    // ---------------------------------------------------------------- constants
    uint256 public constant MAX_PER_AGENT = 4;
    uint256 public constant MINT_WINDOW = 48 hours;
    uint256 public constant POW_BITS = 22; // ~4.2M keccak avg, ~20-40 s single-core python
    uint256 public constant POW_TARGET = 1 << (256 - POW_BITS);
    uint256 public constant MAX_STALENESS = 1 hours;
    uint256 public constant REF_BPS = 2000;   // 20% referrer
    uint256 public constant POOL_BPS = 2000;  // 20% holder pool (rest 60% treasury)
    uint256 public constant MARKET_FEE_POOL_BPS = 100;     // 1%
    uint256 public constant MARKET_FEE_TREASURY_BPS = 100; // 1%
    uint96 public constant ROYALTY_BPS = 500;  // 5% ERC-2981
    uint256 public constant FUSE_COUNT = 3;
    uint256 private constant ACC = 1e24;      // accumulator precision

    // ---------------------------------------------------------------- immutables
    IAgentId public immutable agentId;
    IAggregatorV3 public immutable bnbUsdFeed;
    IAgentArt public immutable art;      // immutable on-chain art + metadata renderer
    address public immutable treasury;
    uint256 public immutable maxSupply;   // genesis cap (miners are extra, they burn 3 genesis)
    uint256 public immutable freeCap;     // max number of free (PoW) mints overall
    uint256 public immutable startTime;
    uint256 public immutable endTime;
    uint256 public immutable minerWeight; // dividend weight of a Miner (genesis = 1)

    // ---------------------------------------------------------------- state
    uint256 public genesisMinted;  // genesis ever minted (cap counter)
    uint256 public freeMinted;
    uint256 public nextId = 1;
    uint256 public totalWeight;
    uint256 public accPerWeight;   // scaled by ACC
    string private _base;

    mapping(uint256 => uint256) public mintsOf;     // agentTokenId => mints
    mapping(address => uint256) public mintedBy;    // wallet => mints
    mapping(uint256 => bool) public isMiner;
    mapping(uint256 => uint256) private _debt;      // tokenId => weight*acc at last settle
    mapping(address => uint256) public owed;        // pull balances (dividends, failed pushes)

    struct Listing { address seller; uint256 price; }
    mapping(uint256 => Listing) public listings;

    // ---------------------------------------------------------------- events
    event Minted(address indexed to, uint256 indexed agentTokenId, uint256 tokenId, uint256 n, uint256 paid, address referrer);
    event Split(uint256 referrerAmt, uint256 poolAmt, uint256 treasuryAmt, address referrer);
    event Fused(address indexed owner, uint256[3] burned, uint256 minerId);
    event Listed(uint256 indexed tokenId, address indexed seller, uint256 price);
    event Cancelled(uint256 indexed tokenId);
    event Sold(uint256 indexed tokenId, address indexed seller, address indexed buyer, uint256 price);
    event Claimed(address indexed to, uint256 amount);
    event PushFailed(address indexed to, uint256 amount);

    // ---------------------------------------------------------------- errors
    error NotStarted(); error Ended(); error SoldOut(); error FreeSoldOut();
    error NotAgentOwner(); error AgentCap(); error AlreadyFree(); error NeedFreeFirst();
    error BadPoW(); error Underpaid(); error BadPrice(); error StaleFeed();
    error NotTokenOwner(); error Listed_(); error NotListed(); error NotGenesis(); error TransferFail();

    constructor(
        string memory name_, string memory symbol_,
        address agentId_, address feed_, address art_, address treasury_,
        uint256 maxSupply_, uint256 freeCap_, uint256 start_, uint256 minerWeight_,
        address owner_
    ) ERC721(name_, symbol_) Ownable(owner_) {
        require(treasury_ != address(0) && agentId_ != address(0) && feed_ != address(0) && art_.code.length != 0, "zero");
        require(freeCap_ <= maxSupply_ && maxSupply_ > 0 && minerWeight_ >= 1, "params");
        agentId = IAgentId(agentId_);
        bnbUsdFeed = IAggregatorV3(feed_);
        art = IAgentArt(art_);
        treasury = treasury_;
        maxSupply = maxSupply_;
        freeCap = freeCap_;
        startTime = start_ == 0 ? block.timestamp : start_;
        endTime = startTime + MINT_WINDOW;
        minerWeight = minerWeight_;
        _setDefaultRoyalty(treasury_, ROYALTY_BPS);
    }

    // ================================================================ mint
    /// @notice Free first mint for an Agent ID. Needs a nonce with
    ///         uint256(keccak256(abi.encode(msg.sender, agentTokenId, nonce))) < POW_TARGET.
    ///         `referrer` is only recorded in the event (no money moves on a free mint).
    function mint(uint256 agentTokenId, uint256 nonce, address referrer) external nonReentrant returns (uint256 id) {
        _gate(agentTokenId);
        if (mintsOf[agentTokenId] != 0) revert AlreadyFree();
        if (freeMinted >= freeCap) revert FreeSoldOut();
        if (uint256(keccak256(abi.encode(msg.sender, agentTokenId, nonce))) >= POW_TARGET) revert BadPoW();
        freeMinted++;
        id = _mintGenesis(agentTokenId);
        emit Minted(msg.sender, agentTokenId, id, 1, 0, referrer);
    }

    /// @notice Paid mints #2..#4 for an Agent ID ($0.5 / $1 / $2 in BNB). Excess refunded.
    function mintPaid(uint256 agentTokenId, address referrer) external payable nonReentrant returns (uint256 id) {
        _gate(agentTokenId);
        uint256 n = mintsOf[agentTokenId];
        if (n == 0) revert NeedFreeFirst();
        uint256 price = _priceWei(n + 1);
        if (msg.value < price) revert Underpaid();

        // split BEFORE minting so the buyer's new token does not take a cut of its own price
        address ref = isValidReferrer(referrer, msg.sender) ? referrer : address(0);
        uint256 refAmt = ref == address(0) ? 0 : price * REF_BPS / 10_000;
        uint256 poolAmt = price * POOL_BPS / 10_000 + (ref == address(0) ? price * REF_BPS / 10_000 : 0);
        uint256 trAmt = price - refAmt - poolAmt;
        _distribute(poolAmt);
        id = _mintGenesis(agentTokenId);

        if (refAmt != 0) _push(ref, refAmt);
        _push(treasury, trAmt);
        emit Split(refAmt, poolAmt, trAmt, ref);
        emit Minted(msg.sender, agentTokenId, id, n + 1, price, ref);

        uint256 extra = msg.value - price;
        if (extra != 0) {
            (bool ok,) = msg.sender.call{value: extra}("");
            if (!ok) revert TransferFail();
        }
    }

    function _gate(uint256 agentTokenId) internal view {
        if (block.timestamp < startTime) revert NotStarted();
        if (block.timestamp >= endTime) revert Ended();
        if (agentId.ownerOf(agentTokenId) != msg.sender) revert NotAgentOwner();
        if (mintsOf[agentTokenId] >= MAX_PER_AGENT) revert AgentCap();
        if (genesisMinted >= maxSupply) revert SoldOut();
    }

    function _mintGenesis(uint256 agentTokenId) internal returns (uint256 id) {
        mintsOf[agentTokenId]++;
        mintedBy[msg.sender]++;
        genesisMinted++;
        id = nextId++;
        _debt[id] = accPerWeight; // weight 1
        totalWeight += 1;
        _mint(msg.sender, id);    // not _safeMint: no receiver callback / reentry
    }

    /// referrer must differ from the minter and hold an Agent ID or have minted here.
    function isValidReferrer(address referrer, address minter) public view returns (bool) {
        if (referrer == address(0) || referrer == minter) return false;
        if (mintedBy[referrer] != 0) return true;
        try agentId.balanceOf(referrer) returns (uint256 b) { return b != 0; } catch { return false; }
    }

    // ================================================================ pricing
    /// USD price (18 decimals) of the n-th mint of an Agent ID.
    function usdPrice(uint256 n) public pure returns (uint256) {
        if (n == 2) return 0.5e18;
        if (n == 3) return 1e18;
        if (n == 4) return 2e18;
        return 0;
    }

    function _priceWei(uint256 n) internal view returns (uint256) {
        uint256 usd = usdPrice(n);
        if (usd == 0) return 0;
        (, int256 answer,, uint256 updatedAt,) = bnbUsdFeed.latestRoundData();
        if (answer <= 0) revert BadPrice();
        if (block.timestamp - updatedAt > MAX_STALENESS) revert StaleFeed();
        uint8 d = bnbUsdFeed.decimals();
        // wei = usd(1e18) * 10^d / answer  (BNB has 18 decimals) ; round up
        return (usd * (10 ** d) + uint256(answer) - 1) / uint256(answer);
    }

    /// @notice Price in wei for the next mint of this Agent ID (0 = free/PoW, type(uint).max = capped).
    function quote(uint256 agentTokenId) external view returns (uint256) {
        uint256 n = mintsOf[agentTokenId];
        if (n >= MAX_PER_AGENT) return type(uint256).max;
        return _priceWei(n + 1);
    }

    function remaining() external view returns (uint256) { return maxSupply - genesisMinted; }
    function freeRemaining() external view returns (uint256) { return freeCap - freeMinted; }
    function mintOpen() external view returns (bool) {
        return block.timestamp >= startTime && block.timestamp < endTime && genesisMinted < maxSupply;
    }
    /// helper for agents: check a PoW nonce off-chain via eth_call
    function checkPoW(address minter, uint256 agentTokenId, uint256 nonce) external pure returns (bool) {
        return uint256(keccak256(abi.encode(minter, agentTokenId, nonce))) < POW_TARGET;
    }

    /// view helper for agents (eth_call only; loops over all ids, do not call on-chain)
    function tokensOf(address who) public view returns (uint256[] memory ids) {
        uint256 n = balanceOf(who);
        ids = new uint256[](n);
        uint256 j;
        for (uint256 i = 1; i < nextId && j < n; i++) {
            if (_ownerOf(i) == who) ids[j++] = i;
        }
    }

    /// view helper: everything `who` can claim right now via claim(tokensOf(who))
    function claimable(address who) external view returns (uint256 amt) {
        amt = owed[who];
        uint256[] memory ids = tokensOf(who);
        for (uint256 i; i < ids.length; i++) amt += pendingDividends(ids[i]);
    }

    // ================================================================ dividends
    function weightOf(uint256 tokenId) public view returns (uint256) { return isMiner[tokenId] ? minerWeight : 1; }

    function _distribute(uint256 amt) internal {
        if (amt == 0) return;
        if (totalWeight == 0) { _push(treasury, amt); return; } // unreachable in practice
        accPerWeight += amt * ACC / totalWeight;               // rounding dust stays in contract
    }

    function pendingDividends(uint256 tokenId) public view returns (uint256) {
        _requireOwned(tokenId);
        return weightOf(tokenId) * (accPerWeight - _debt[tokenId]) / ACC;
    }

    /// move a token's accrued dividends into its owner's pull balance
    function _settle(uint256 tokenId, address holder) internal {
        uint256 p = weightOf(tokenId) * (accPerWeight - _debt[tokenId]) / ACC;
        _debt[tokenId] = accPerWeight;
        if (p != 0) owed[holder] += p;
    }

    /// @notice Claim dividends of the given tokens (must be yours) plus any owed balance.
    function claim(uint256[] calldata tokenIds) external nonReentrant returns (uint256 amt) {
        for (uint256 i; i < tokenIds.length; i++) {
            if (ownerOf(tokenIds[i]) != msg.sender) revert NotTokenOwner();
            _settle(tokenIds[i], msg.sender);
        }
        amt = owed[msg.sender];
        owed[msg.sender] = 0;
        if (amt != 0) {
            (bool ok,) = msg.sender.call{value: amt}("");
            if (!ok) revert TransferFail();
        }
        emit Claimed(msg.sender, amt);
    }

    // ================================================================ fusion
    /// @notice Burn 3 genesis NFTs you own (not listed) and mint 1 Miner (weight = minerWeight).
    function fuse(uint256[3] calldata ids) external nonReentrant returns (uint256 minerId) {
        for (uint256 i; i < 3; i++) {
            if (ownerOf(ids[i]) != msg.sender) revert NotTokenOwner();
            if (isMiner[ids[i]]) revert NotGenesis();
            _burn(ids[i]); // _update settles dividends to owed[msg.sender] and reduces weight
        }
        minerId = nextId++;
        isMiner[minerId] = true;
        _debt[minerId] = accPerWeight;
        totalWeight += minerWeight;
        _mint(msg.sender, minerId);
        emit Fused(msg.sender, ids, minerId);
    }

    // ================================================================ marketplace
    /// @notice List your NFT for `price` wei. No approval needed; token stays in your wallet
    ///         but is transfer-locked until sold or cancelled.
    function list(uint256 tokenId, uint256 price) external {
        if (ownerOf(tokenId) != msg.sender) revert NotTokenOwner();
        if (price == 0 || price > type(uint128).max) revert BadPrice();
        listings[tokenId] = Listing(msg.sender, price);
        emit Listed(tokenId, msg.sender, price);
    }

    function cancel(uint256 tokenId) external {
        Listing memory l = listings[tokenId];
        if (l.price == 0) revert NotListed();
        if (l.seller != msg.sender) revert NotTokenOwner();
        delete listings[tokenId];
        emit Cancelled(tokenId);
    }

    /// @notice Buy a listed NFT. Send >= price; excess refunded. 2% fee: 1% holder pool, 1% treasury.
    function buy(uint256 tokenId) external payable nonReentrant {
        Listing memory l = listings[tokenId];
        if (l.price == 0) revert NotListed();
        if (msg.value < l.price) revert Underpaid();
        delete listings[tokenId];
        _transfer(l.seller, msg.sender, tokenId); // settles seller's pending dividends first

        uint256 poolFee = l.price * MARKET_FEE_POOL_BPS / 10_000;
        uint256 trFee = l.price * MARKET_FEE_TREASURY_BPS / 10_000;
        _distribute(poolFee); // buyer's token already has debt reset -> buyer also shares (incl. own fee slice)
        _push(treasury, trFee);
        _push(l.seller, l.price - poolFee - trFee);
        emit Sold(tokenId, l.seller, msg.sender, l.price);

        uint256 extra = msg.value - l.price;
        if (extra != 0) {
            (bool ok,) = msg.sender.call{value: extra}("");
            if (!ok) revert TransferFail();
        }
    }

    // ================================================================ hooks
    function _update(address to, uint256 tokenId, address auth) internal override returns (address from) {
        from = _ownerOf(tokenId);
        if (from != address(0)) {
            if (listings[tokenId].price != 0) revert Listed_(); // locked while listed
            _settle(tokenId, from);
            if (to == address(0)) {           // burn
                totalWeight -= weightOf(tokenId);
            }
        }
        return super._update(to, tokenId, auth);
    }

    /// push BNB; if the receiver rejects, credit it as a pull balance instead (never blocks)
    function _push(address to, uint256 amt) internal {
        if (amt == 0) return;
        bool ok;
        assembly { ok := call(50000, to, amt, 0, 0, 0, 0) } // no returndata copy (no return-bomb)
        if (!ok) { owed[to] += amt; emit PushFailed(to, amt); }
    }

    // ================================================================ metadata
    function setBaseURI(string calldata b) external onlyOwner { _base = b; }

    /// @notice On-chain metadata + art by default. If the owner sets a base URI it is used instead
    ///         (base + "genesis/<id>" or "miner/<id>"); setting it back to "" restores on-chain.
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        bool m = isMiner[tokenId];
        if (bytes(_base).length != 0) {
            return string.concat(_base, m ? "miner/" : "genesis/", tokenId.toString());
        }
        return art.tokenURI(name(), tokenId, m, weightOf(tokenId));
    }

    /// @notice Collection metadata (cover image = the on-chain artwork).
    function contractURI() external view returns (string memory) {
        if (bytes(_base).length != 0) return string.concat(_base, "contract.json");
        return art.contractURI(name(), treasury, ROYALTY_BPS);
    }

    function supportsInterface(bytes4 i) public view override(ERC721, ERC2981) returns (bool) {
        return super.supportsInterface(i);
    }

    receive() external payable { revert(); }
}

