// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721Enumerable} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {SignatureChecker} from "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
interface IOfficialAgentID {function ownerOf(uint256 id) external view returns(address);}

/// @notice An independent collection. No sale duration, sell-out-only end, immediate ERC721 transfers.
contract PatchworldNFT is ERC721Enumerable,ReentrancyGuard,Ownable2Step,EIP712 {
 uint256 public constant MAX_SUPPLY=8888;
 uint256 public constant MAX_PER_ID=10;
 uint256 public immutable mintPrice;
 IOfficialAgentID public immutable identity;
 bytes32 public immutable identityCodeHash;
 address payable public immutable proceedsRecipient;
 address public repairSigner;
 uint256 public totalMinted;
 bool public mintEnabled;
 string public metadataBase;
 uint256 public metadataVersion;
 bool public metadataFrozen;
 mapping(uint256=>uint256) public mintedByIdentity;
 mapping(uint256=>uint256) public transferVersion;
 mapping(uint256=>bool) public repairDayOpen;
 mapping(uint256=>uint256) public repairDayCount;
 mapping(uint256=>mapping(uint256=>bool)) public repairedOnDay;
 bytes32 public constant REPAIR_TYPEHASH=keccak256("RepairMint(address wallet,uint256 identityId,uint256 expectedMinted,uint256 day,uint256 deadline,bytes32 taskId)");
 mapping(bytes32=>bool) public repairUsed;
 error Invalid();error Ineligible();error Unavailable();error StalePreview();error WrongPayment();error PaymentFailed();
 event Minted(address indexed wallet,uint256 indexed identityId,uint256 firstTokenId,uint256 quantity,uint256 paid,uint8 path);
 event ProceedsPaid(address indexed recipient,uint256 amount);
 event RepairDayChanged(uint256 indexed day,bool open);
 event RepairSignerChanged(address indexed signer);
 event MetadataBaseChanged(string base,uint256 version);
 event MetadataFrozen(string base);
 event BatchMetadataUpdate(uint256 fromTokenId,uint256 toTokenId);
 constructor(string memory name_,string memory symbol_,address registry,bytes32 registryHash,address admin,address payable recipient,address signer,uint256 price)
 ERC721(name_,symbol_) Ownable(admin) EIP712("P1XO Repair","1") {
  if(bytes(name_).length==0||bytes(symbol_).length==0||registry.code.length==0||registry.codehash!=registryHash||admin==address(0)||recipient==address(0)||price==0)revert Invalid();
  identity=IOfficialAgentID(registry);identityCodeHash=registryHash;proceedsRecipient=recipient;repairSigner=signer;mintPrice=price;mintEnabled=true;
 }
 function mintEnded()public view returns(bool){return totalMinted>=MAX_SUPPLY;}
 function setMintEnabled(bool enabled)external onlyOwner{mintEnabled=enabled;}
 function setRepairSigner(address signer)external onlyOwner{repairSigner=signer;emit RepairSignerChanged(signer);}
 function setMetadataBase(string calldata base)external onlyOwner{
  if(metadataFrozen||bytes(base).length==0||bytes(base).length>256)revert Invalid();metadataBase=base;metadataVersion++;emit MetadataBaseChanged(base,metadataVersion);if(totalMinted>0)emit BatchMetadataUpdate(1,totalMinted);
 }
 function freezeMetadata()external onlyOwner{if(metadataFrozen||bytes(metadataBase).length==0)revert Invalid();metadataFrozen=true;emit MetadataFrozen(metadataBase);}
 function quote(uint256 identityId,uint256 quantity)public view returns(uint256){
  uint256 used=mintedByIdentity[identityId];if(quantity==0||quantity>MAX_PER_ID-used||quantity>MAX_SUPPLY-totalMinted)revert Invalid();return (quantity-(used==0?1:0))*mintPrice;
 }
 function _identityOwner(uint256 id,address wallet)internal view{
  if(address(identity).codehash!=identityCodeHash)revert Unavailable();if(identity.ownerOf(id)!=wallet)revert Ineligible();
 }
 function mint(uint256 identityId,uint256 quantity,uint256 expectedMinted)external payable nonReentrant{
  if(!mintEnabled||mintEnded())revert Unavailable();_identityOwner(identityId,msg.sender);
  if(mintedByIdentity[identityId]!=expectedMinted)revert StalePreview();uint256 cost=quote(identityId,quantity);if(msg.value!=cost)revert WrongPayment();
  _mintBatch(identityId,quantity,cost,0);
 }
 function setRepairDay(uint256 day,bool open)external onlyOwner{
  if(day!=block.timestamp/1 days||repairSigner==address(0))revert Invalid();repairDayOpen[day]=open;emit RepairDayChanged(day,open);
 }
 function mintRepair(uint256 identityId,uint256 expectedMinted,uint256 day,uint256 deadline,bytes32 taskId,bytes calldata signature)external nonReentrant{
  if(!mintEnabled||mintEnded()||repairSigner==address(0)||day!=block.timestamp/1 days||!repairDayOpen[day]||block.timestamp>deadline||repairDayCount[day]>=100)revert Unavailable();
  _identityOwner(identityId,msg.sender);if(expectedMinted==0||expectedMinted!=mintedByIdentity[identityId])revert StalePreview();
  if(expectedMinted>=MAX_PER_ID||repairedOnDay[day][identityId]||repairUsed[taskId]||taskId==bytes32(0))revert Invalid();
  bytes32 hash=_hashTypedDataV4(keccak256(abi.encode(REPAIR_TYPEHASH,msg.sender,identityId,expectedMinted,day,deadline,taskId)));
  if(!SignatureChecker.isValidSignatureNow(repairSigner,hash,signature))revert Ineligible();
  repairedOnDay[day][identityId]=true;repairDayCount[day]++;repairUsed[taskId]=true;_mintBatch(identityId,1,0,1);
 }
 function _mintBatch(uint256 identityId,uint256 quantity,uint256 paid,uint8 path)private{
  uint256 first=totalMinted+1;totalMinted+=quantity;mintedByIdentity[identityId]+=quantity;
  for(uint256 id=first;id<first+quantity;id++)_safeMint(msg.sender,id);
  if(paid!=0){(bool ok,)=proceedsRecipient.call{value:paid}("");if(!ok)revert PaymentFailed();emit ProceedsPaid(proceedsRecipient,paid);}
  emit Minted(msg.sender,identityId,first,quantity,paid,path);
 }
 /// No secret or fair-rarity claim: the serial identity art is deterministic and immediately available.
 function tokenURI(uint256 id)public view override returns(string memory){
  _requireOwned(id);string memory number=Strings.toString(id);if(bytes(metadataBase).length!=0)return string.concat(metadataBase,number,'.json');
  // A self-contained pixel silhouette plus a 16-bit serial pattern; metadata needs no server.
  string memory pixels='';for(uint256 i;i<16;i++)if((id&(1<<i))!=0)pixels=string.concat(pixels,'<rect x="',Strings.toString(16+(i%4)*8),'" y="',Strings.toString(40+(i/4)*3),'" width="6" height="2" fill="#b7ed86"/>');
  string memory svg=string.concat('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" shape-rendering="crispEdges"><rect width="64" height="64" fill="#101820"/><path d="M30 5h4v7h-4zM17 12h30v23H17zM11 35h42v7H11zM20 35h24v18H20zM19 53h11v7H19zM34 53h11v7H34z" fill="#849c95"/><path d="M21 17h22v12H21z" fill="#101820"/><path d="M24 21h7v3h-7zM34 21h7v3h-7z" fill="#b7ed86"/>',pixels,'<text x="32" y="63" text-anchor="middle" font-size="3" fill="#d7e7ca">#',number,'</text></svg>');
  return string.concat('data:application/json;base64,',Base64.encode(bytes(string.concat('{"name":"',name(),' #',number,'","description":"Pixel Agent identity. Immediate transferability. No fixed token reward or rarity promise.","image":"data:image/svg+xml;base64,',Base64.encode(bytes(svg)),'","attributes":[{"trait_type":"Serial","value":',number,'}]}'))));
 }
 function _update(address to,uint256 id,address auth)internal override returns(address from){from=super._update(to,id,auth);if(from!=address(0))transferVersion[id]++;}
 function supportsInterface(bytes4 interfaceId)public view override returns(bool){return interfaceId==0x49064906||super.supportsInterface(interfaceId);}
}
